class BaseDevice {
    public BaseDevice() {
        System.out.println("1. BaseDevice constructor starting");
        // DANGEROUS ANTI-PATTERN: Calling overridable method from constructor!
        initHardware();
    }
    public void initHardware() {
        System.out.println("   Base hardware default init");
    }
}

class SmartSensor extends BaseDevice {
    // Subclass field initialized inline
    private String sensorId = "SENS-999";

    @Override
    public void initHardware() {
        // DANGER: When called from BaseDevice constructor, sensorId is STILL NULL!
        System.out.println("   SmartSensor initializing: " + sensorId.toLowerCase());
    }
}

public class ConstructorTrapDemo {
    public static void main(String[] args) {
        // Watch the crash:
        try {
            SmartSensor s = new SmartSensor();
        } catch (NullPointerException e) {
            System.out.println("CRASHED! sensorId was null during super() constructor call!");
        }
    }
}

