class SafeBaseDevice {
    public SafeBaseDevice() {
        System.out.println("1. Base constructor safely initialized without virtual calls");
    }
    // Explicit lifecycle method called AFTER full object construction
    public void initialize() {
        onInitialize();
    }
    protected void onInitialize() {
        System.out.println("   Base device initialized");
    }
}

class SafeSmartSensor extends SafeBaseDevice {
    private String sensorId;

    public SafeSmartSensor(String sensorId) {
        super(); // Super runs cleanly first
        this.sensorId = sensorId; // Field fully initialized
    }

    @Override
    protected void onInitialize() {
        System.out.println("   Sensor initialized with ID: " + sensorId.toLowerCase());
    }
}

public class SafeInitializationDemo {
    public static void main(String[] args) {
        SafeSmartSensor sensor = new SafeSmartSensor("SENS-999");
        sensor.initialize(); // Called after construction is 100% complete
    }
}

