import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class SecurityToken {
    private final String tokenId;
    private final List<String> permissions;

    public SecurityToken(String tokenId, List<String> permissions) {
        this.tokenId = tokenId;
        this.permissions = (permissions != null) ? new ArrayList<>(permissions) : new ArrayList<>();
    }
    public String getTokenId() { return tokenId; }
    public List<String> getPermissions() {
        return Collections.unmodifiableList(permissions);
    }
}

public class TokenApp {
    public static void main(String[] args) {
        List<String> perms = new ArrayList<>();
        perms.add("READ");
        perms.add("WRITE");

        SecurityToken token = new SecurityToken("tok-100", perms);
        perms.add("ADMIN_DELETE");

        System.out.println("Token permissions count: " + token.getPermissions().size());

        try {
            token.getPermissions().add("HACK");
        } catch (UnsupportedOperationException e) {
            System.out.println("Immutable protection verified");
        }
    }
}

