class Product {
    private int id;
    public Product(int id) { this.id = id; }

    // BUG: Accidental overload! Signature does not match Object.equals(Object)!
    public boolean equals(Product p) {
        if (p == null) return false;
        return this.id == p.id;
    }
}

public class OverloadBug {
    public static void main(String[] args) {
        Object p1 = new Product(101);
        Object p2 = new Product(101);

        // Invoked through Object reference: calls Object.equals(Object) which checks reference identity!
        System.out.println("Equal products: " + p1.equals(p2));
    }
}

