class Product {
    private int id;
    public Product(int id) { this.id = id; }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj instanceof Product p) {
            return this.id == p.id;
        }
        return false;
    }

    @Override
    public int hashCode() {
        return Integer.hashCode(id);
    }
}

public class OverloadBug {
    public static void main(String[] args) {
        Object p1 = new Product(101);
        Object p2 = new Product(101);

        System.out.println("Equal products: " + p1.equals(p2));
    }
}

interface TelemetryPacket {
    long getTimestamp();
    String getPacketType();
}

class GpsPacket implements TelemetryPacket {
    private long timestamp;
    private double latitude, longitude;
    public GpsPacket(long timestamp, double lat, double lon) {
        this.timestamp = timestamp;
        this.latitude = lat;
        this.longitude = lon;
    }
    @Override public long getTimestamp() { return timestamp; }
    @Override public String getPacketType() { return "GPS"; }
    public double getLatitude() { return latitude; }
    public double getLongitude() { return longitude; }
}

class EnginePacket implements TelemetryPacket {
    private long timestamp;
    private int rpm;
    private double temp;
    public EnginePacket(long timestamp, int rpm, double temp) {
        this.timestamp = timestamp;
        this.rpm = rpm;
        this.temp = temp;
    }
    @Override public long getTimestamp() { return timestamp; }
    @Override public String getPacketType() { return "ENGINE"; }
    public int getRpm() { return rpm; }
    public double getTemp() { return temp; }
}

class TelemetryAuditor {
    public static void audit(TelemetryPacket[] packets) {
        for (TelemetryPacket p : packets) {
            if (p instanceof GpsPacket g) {
                System.out.println("[GPS @ " + g.getTimestamp() + "] Lat: " + g.getLatitude() + ", Lon: " + g.getLongitude());
            } else if (p instanceof EnginePacket e) {
                System.out.println("[ENGINE @ " + e.getTimestamp() + "] RPM: " + e.getRpm() + ", Temp: " + e.getTemp() + "C");
            }
        }
    }
}

public class TelemetryApp {
    public static void main(String[] args) {
        TelemetryPacket[] packets = new TelemetryPacket[] {
            new GpsPacket(1000L, 37.7749, -122.4194),
            new EnginePacket(1050L, 3200, 88.5),
            null
        };
        TelemetryAuditor.audit(packets);
    }
}
